function TimelineGame() {
  const theme = themes.timeline; const [cards, setCards] = useState(() => shuffle(timelineEvents)); const [chosen, setChosen] = useState<string[]>([]); const [mistakes, setMistakes] = useState(0); const [finished, setFinished] = useState(false); const correct = useMemo(() => [...timelineEvents].sort((a, b) => a.year - b.year), []);
  const pick = (label: string) => { if (chosen.includes(label)) return; if (label === correct[chosen.length].label) { const next = [...chosen, label]; setChosen(next); Haptics.selectionAsync(); if (next.length === correct.length) setFinished(true); } else { setMistakes(v => v + 1); Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error); } };
  const restart = () => { setCards(shuffle(timelineEvents)); setChosen([]); setMistakes(0); setFinished(false); };
  if (finished) return <Result id="timeline" score={Math.max(0, correct.length - mistakes)} total={correct.length} onReplay={restart} />;
  return <ScrollView style={{ backgroundColor: theme.dark }} contentContainerStyle={styles.gameContent} showsVerticalScrollIndicator={false}><Hud id="timeline" current={chosen.length} total={correct.length} score={Math.max(0, chosen.length - mistakes)} /><ImageBackground source={categoryArtPool[2]} style={styles.gameQuestionStage}><View style={styles.gameQuestionShade} /><View style={[styles.stageBadge, { backgroundColor: theme.accent }]}><Ionicons name="hourglass" size={13} color={theme.dark} /><Text style={[styles.stageBadgeText, { color: theme.dark }]}>TIME QUEST</Text></View></ImageBackground><View style={styles.timelineHeading}><View style={[styles.timelineDial, { borderColor: theme.accent }]}><Ionicons name="hourglass" size={27} color={theme.accent} /></View><View><Text style={styles.promptSmall}>Build history</Text><Text style={styles.instruction}>Choose the oldest remaining event.</Text></View></View><View style={styles.timelineTrack}><View style={[styles.trackLine, { backgroundColor: `${theme.accent}70` }]} />{cards.map((item, i) => { const done = chosen.includes(item.label); return <Pressable key={item.label} disabled={done} onPress={() => pick(item.label)} style={({ pressed }) => [styles.timelineCard, pressed && !done && { transform: [{ scale: .98 }], borderColor: theme.accent }, done && { borderColor: theme.accent, backgroundColor: `${theme.accent}20` }]}><View style={[styles.station, { backgroundColor: done ? theme.accent : theme.dark, borderColor: theme.accent }]}><Text style={[styles.stationText, done && { color: theme.dark }]}>{done ? chosen.indexOf(item.label) + 1 : i + 1}</Text></View><View style={{ flex: 1 }}><Text style={[styles.timelineYear, { color: done ? theme.accent : 'rgba(255,255,255,.48)' }]}>{done ? (item.year < 0 ? `${Math.abs(item.year)} BCE` : item.year) : 'DATE LOCKED'}</Text><Text style={styles.timelineText}>{item.label}</Text></View>{done ? <Ionicons name="checkmark-circle" size={23} color={theme.accent} /> : <Ionicons name="chevron-forward" size={18} color={theme.secondary} />}</Pressable>; })}</View><View style={styles.mistakePill}><Ionicons name="heart" size={14} color="#FF6174" /><Text style={styles.mistakes}>{Math.max(0, 3 - mistakes)} lives left</Text></View></ScrollView>;
}

type MatchCard = { id: string; pair: number; label: string };
function MatchGame() {
  const theme = themes.match; const makeDeck = () => shuffle(matchPairs.flatMap((pair, pairIndex) => pair.map((label, index) => ({ id: `${pairIndex}-${index}`, pair: pairIndex, label })))); const [deck, setDeck] = useState<MatchCard[]>(makeDeck); const [open, setOpen] = useState<string[]>([]); const [matched, setMatched] = useState<number[]>([]); const [moves, setMoves] = useState(0); const [finished, setFinished] = useState(false);
  useEffect(() => { if (open.length !== 2) return; const [a, b] = open.map(cardId => deck.find(card => card.id === cardId)!); const timer = setTimeout(() => { if (a.pair === b.pair) { const next = [...matched, a.pair]; setMatched(next); Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success); if (next.length === matchPairs.length) setFinished(true); } else Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error); setOpen([]); }, 650); return () => clearTimeout(timer); }, [open, deck, matched]);
  const flip = (card: MatchCard) => { if (open.length === 2 || open.includes(card.id) || matched.includes(card.pair)) return; Haptics.selectionAsync(); setOpen(v => [...v, card.id]); if (open.length === 1) setMoves(v => v + 1); }; const restart = () => { setDeck(makeDeck()); setOpen([]); setMatched([]); setMoves(0); setFinished(false); };
  if (finished) return <Result id="match" score={Math.max(1, 12 - Math.max(0, moves - 4))} total={12} onReplay={restart} />;
  return <ScrollView style={{ backgroundColor: theme.dark }} contentContainerStyle={styles.gameContent} showsVerticalScrollIndicator={false}><Hud id="match" current={matched.length} total={matchPairs.length} score={matched.length} /><View style={styles.matchHeading}><View><Text style={styles.promptSmall}>Flip. Think. Match.</Text><Text style={styles.instruction}>Pair every image with its related image.</Text></View><View style={[styles.movesBadge, { borderColor: `${theme.accent}66` }]}><Text style={[styles.movesNumber, { color: theme.accent }]}>{moves}</Text><Text style={styles.movesLabel}>MOVES</Text></View></View><View style={styles.matchGrid}>{deck.map((card, index) => { const visible = open.includes(card.id) || matched.includes(card.pair); const done = matched.includes(card.pair); const cardAccent = index % 2 ? theme.secondary : theme.accent; return <Pressable key={card.id} onPress={() => flip(card)} style={({ pressed }) => [styles.matchCard, { borderColor: `${cardAccent}55`, shadowColor: cardAccent }, pressed && !visible && { transform: [{ scale: .94 }] }, done && styles.imageAnswerCorrect]}>{visible ? <ImageBackground source={matchArtByLabel[card.label]} style={styles.matchPhoto} imageStyle={styles.matchPhotoRadius}>{done && <View style={styles.imageAnswerState}><Ionicons name="checkmark" size={14} color="#07110A" /></View>}</ImageBackground> : <View style={[styles.matchBack, { backgroundColor: `${cardAccent}1A` }]}><View style={[styles.cardMark, { borderColor: `${cardAccent}70`, backgroundColor: `${cardAccent}22` }]}><Ionicons name="sparkles" size={20} color={cardAccent} /></View><Text style={[styles.cardNumber, { color: cardAccent }]}>CARD {index + 1}</Text></View>}</Pressable>; })}</View></ScrollView>;
}

